INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(10297, 'plPL', 'Otwarcie Mrocznego Portalu', 'Za tym szlakiem czasu, w sercu Czarnych Mokradeł, Strażnik Medivh gorączkowo pracuje nad otwarciem Mrocznego Portalu, które zwiastuje nadejście ery orków w Azeroth.$B$BNieskończeni wysłali swoich władców szczelin, by do tego nie dopuścić.$B$BW różnych miejscach mokradeł będą się pojawiać szczeliny. Wyroją się z nich Nieskończeni i spróbują zniszczyć tarcze Medivha, a w końcu jego samego.$B$BZabijaj ich władców szczelin i przywódców! Rób to, dopóki Medivh nie odniesie sukcesu. Jeśli będziesz potrzebować pomocy, użyj tej chronolatarni.', 'Sa\'at na Czarnych Mokradłach w Jaskiniach Czasu powierzył ci zadanie obrony Medivha, dopóki ten nie otworzy Mrocznego Portalu.$B$BJeśli ci się uda, wróć do Sa\'ata.', 'Mroczny Portal otwarty', 'Wróć do Sa\'ata na Czarnych Mokradłach.', '', '', '', '', 0);
